  const readState = () => {
    try {
      const value = JSON.parse(localStorage.getItem(storageKey));
      return value && typeof value === "object" ? value : {};
    } catch {
      return {};
    }
  };

  const saveState = (state) => {
    try {
      localStorage.setItem(storageKey, JSON.stringify(state));
    } catch {
      // Navigation and the query-string selection still work without storage.
    }
  };

  document.querySelectorAll("[data-select-task]").forEach((link) => {
    link.addEventListener("click", () => {
      saveState({ ...readState(), task: link.dataset.selectTask });
    });
  });

  document.querySelectorAll("[data-select-approach]").forEach((link) => {
    link.addEventListener("click", () => {
      saveState({ ...readState(), approach: link.dataset.selectApproach });
    });
  });

